#!/bin/bash
# serve DeepSeek-V4.1-Flash from both nodes (rank 1 first, detached; rank 0 in the foreground):
#   tools/dsv41_serve2.sh [extra serve args...]      e.g. --port 8899 --context 65536
set -e
cd /home/urtho/dev/_experiments/ai/tensorfold
rsync -a --exclude .venv --exclude .git --exclude notes/ref --exclude out --exclude __pycache__ --exclude .claude ./ aiai:tensorfold/
rsync -a --exclude .venv --exclude .git --exclude notes/ref --exclude out --exclude __pycache__ --exclude .claude ./ aiai2:tensorfold/
for h in aiai aiai2; do timeout 30 ssh $h "docker exec tf-dev pkill -f 'tensorfold serve|tools/dsv41_' ; true" >/dev/null 2>&1; done
# wait until the old ranks have exited (their memory is back), at most 2 minutes
for h in aiai aiai2; do
  for i in $(seq 1 60); do
    timeout 10 ssh $h "docker exec tf-dev pgrep -f 'tensorfold serve|tools/dsv41_'" >/dev/null 2>&1 || break
    sleep 2
  done
done
sleep 2
# no fixed GID index: the index of a port's RoCE v2 IPv4 GID moves (3 or 4, per device) when an address is re-added
# under a live connection; NCCL picks it per device by version and family, the RoCE all-gather by type and address.
# NCCL_IB_GID_INDEX=N in the caller's environment still pins it.
GIDENV="-e NCCL_IB_ROCE_VERSION_NUM=2 -e NCCL_IB_ADDR_FAMILY=AF_INET -e NCCL_IB_ADDR_RANGE=${NCCL_IB_ADDR_RANGE:-10.42.0.0/15}"
[ -n "${NCCL_IB_GID_INDEX:-}" ] && GIDENV="$GIDENV -e NCCL_IB_GID_INDEX=$NCCL_IB_GID_INDEX"
M=/models/dsv41/DeepSeek-V4.1-Flash-EXL3-2.9bpw
ENV="-e TF_DSV41_FIXED_GIB=${TF_DSV41_FIXED_GIB:-} -e TF_CARVEOUT=${TF_CARVEOUT:-} -e TF_MULTI_CHECK=${TF_MULTI_CHECK:-} -e TF_DSV41_WARM=${TF_DSV41_WARM:-} -e TF_DSV41_KV_FP8=${TF_DSV41_KV_FP8:-} -e TF_DSV41_KV=${TF_DSV41_KV:-} -e TF_DSV41_IQ_FP4=${TF_DSV41_IQ_FP4:-} -e TF_DSV41_SWA_FP8=${TF_DSV41_SWA_FP8:-} -e TF_DSV41_COMP_BF16=${TF_DSV41_COMP_BF16:-} -e TF_STEP_THREADS=${TF_STEP_THREADS:-} -e TF_MULTI_DRAFTS=${TF_MULTI_DRAFTS:-} -e TF_MULTI_PROF=${TF_MULTI_PROF:-} -e TF_SPLIT_READS=${TF_SPLIT_READS:-} -e TF_SKIP_SHARED=${TF_SKIP_SHARED:-} -e TF_FOLD_SHARED=${TF_FOLD_SHARED:-} -e TF_ROUTER_SLICES=${TF_ROUTER_SLICES:-} -e TF_L2_PREFETCH=${TF_L2_PREFETCH:-} -e TF_COPY_DRAFTS=${TF_COPY_DRAFTS:-} -e TF_COPY_MAX=${TF_COPY_MAX:-} -e TF_COMM=${TF_COMM:-} -e TF_RDMA_MAX_KB=${TF_RDMA_MAX_KB:-} -e TF_ONE_GRAPH=${TF_ONE_GRAPH:-} -e TF_DSV41_SHARED_POOL=${TF_DSV41_SHARED_POOL:-} -e TF_DSV41_POOL_TOKENS=${TF_DSV41_POOL_TOKENS:-} -e TF_DSV41_KEPT_ENTRIES=${TF_DSV41_KEPT_ENTRIES:-} -e TF_DSV41_KEEP_MIN=${TF_DSV41_KEEP_MIN:-} -e TF_DSV41_POOL_KEEP=${TF_DSV41_POOL_KEEP:-} -e TF_DSV41_GROW_AHEAD=${TF_DSV41_GROW_AHEAD:-} -e TF_DSV41_MEMLOG=${TF_DSV41_MEMLOG:-} -e TF_DSV41_WIDTHS=${TF_DSV41_WIDTHS:-} -e TF_DSV41_SHARED_GRAPHS=${TF_DSV41_SHARED_GRAPHS:-} -e PYTORCH_CUDA_ALLOC_CONF=${PYTORCH_CUDA_ALLOC_CONF:-} -e NUMPY_MADVISE_HUGEPAGE=0 -e MIMALLOC_ALLOW_THP=0 -e TF_DSV41_BOUNDED_TAIL=${TF_DSV41_BOUNDED_TAIL:-} -e TF_DSV41_FAST_TOPK=${TF_DSV41_FAST_TOPK:-} -e TF_DSV41_SELECT_ONCE=${TF_DSV41_SELECT_ONCE:-} -e TF_DSV41_SEG_ROWS=${TF_DSV41_SEG_ROWS:-} -e TF_DSV41_FULL_DEQ=${TF_DSV41_FULL_DEQ:-} -e TF_DSV41_FULL_DEQ_MIB=${TF_DSV41_FULL_DEQ_MIB:-} -e TF_DSV41_PREPARED=${TF_DSV41_PREPARED:-} -e TF_DSV41_TOOL_GRAMMAR=${TF_DSV41_TOOL_GRAMMAR:-} -e TF_DSV41_DISK=${TF_DSV41_DISK:-} -e TF_DSV41_DISK_GIB=${TF_DSV41_DISK_GIB:-} -e TF_DSV41_DISK_MIN=${TF_DSV41_DISK_MIN:-} -e TF_DSV41_DISK_GAIN=${TF_DSV41_DISK_GAIN:-} -e TF_DSV41_DISK_STAGE_MIB=${TF_DSV41_DISK_STAGE_MIB:-} -e TF_EXPERT_LOADS=${TF_EXPERT_LOADS:-} -e TF_EXPERT_LOADS_CFG=${TF_EXPERT_LOADS_CFG:-} -e TF_X3LD_ORDER=${TF_X3LD_ORDER:-} -e TF_EXPERT_GROUP=${TF_EXPERT_GROUP:-} -e TF_X3LD_PDL=${TF_X3LD_PDL:-} -e TF_DSV41_CAND_BOUND=${TF_DSV41_CAND_BOUND:-} -e TF_DSV41_ROUTE_WARPS=${TF_DSV41_ROUTE_WARPS:-} -e TF_ROUTER_BE=${TF_ROUTER_BE:-} -e TF_DSV41_TOPK_DIGITS=${TF_DSV41_TOPK_DIGITS:-} -e TF_DSV41_IDX_FORK=${TF_DSV41_IDX_FORK:-} -e TF_DSV41_PREFILL_PROF=${TF_DSV41_PREFILL_PROF:-} -e TF_DSV41_PREFILL_AHEAD=${TF_DSV41_PREFILL_AHEAD:-} -e TF_L2_ATTN_WQB_MB=${TF_L2_ATTN_WQB_MB:-} -e TF_L2_PREFETCH=${TF_L2_PREFETCH:-} -e PYTHONPATH=/tf/src -e TF_DSV41_ENGRAM_DIR=/models/dsv41/DeepSeek-V4.1-Flash-engram $GIDENV -e NCCL_DEBUG=ERROR -e TF_DSV41_L2_DISCARD=${TF_DSV41_L2_DISCARD:-} -e TF_DSV41_L2_DISCARD_ROWS=${TF_DSV41_L2_DISCARD_ROWS:-} -e TF_DSV41_RES_FOLD=${TF_DSV41_RES_FOLD:-} -e TF_RDMA_TRACE=${TF_RDMA_TRACE:-} -e TF_RDMA_COPY=${TF_RDMA_COPY:-} -e TF_DSV41_SEND=${TF_DSV41_SEND:-} -e TF_DSV41_COSTS=${TF_DSV41_COSTS:-} -e TF_DSV41_ROT_FUSE=${TF_DSV41_ROT_FUSE:-} -e TF_DSV41_WARM_SERVING=${TF_DSV41_WARM_SERVING:-} -e TF_DSV41_WARM_RARE=${TF_DSV41_WARM_RARE:-} -e TF_DSV41_WARM_TRACE=${TF_DSV41_WARM_TRACE:-} -e TF_DSV41_PDL=${TF_DSV41_PDL:-} -e TF_DSV41_DRAFT_GROUP=${TF_DSV41_DRAFT_GROUP:-} -e TF_EXL3_LANES=${TF_EXL3_LANES:-} -e TF_EXL3_LANES_HEAD=${TF_EXL3_LANES_HEAD:-}"
timeout 30 ssh aiai2 "docker exec -d $ENV -e NCCL_SOCKET_IFNAME=enP2p1s0f1np1 -e NCCL_IB_HCA==roceP2p1s0f1,rocep1s0f1 tf-dev bash -c 'cd /tf && python -m tensorfold serve $M --tp 2 --rank 1 --master 10.42.0.1 $* > /tf/serve-r1.log 2>&1'"
exec ssh aiai "docker exec $ENV -e NCCL_SOCKET_IFNAME=enP2p1s0f1np1 -e NCCL_IB_HCA==roceP2p1s0f1,rocep1s0f1 tf-dev bash -c 'cd /tf && python -m tensorfold serve $M --tp 2 --rank 0 --master 10.42.0.1 --host 0.0.0.0 $* 2>&1 | grep --line-buffered -v -E \"Warning|USDT\"'"
